   schemaVersion: z.literal(CODEX_REVIEW_VERDICT_SCHEMA),
   decision: z.enum(['pass', 'fail', 'blocked']),
   materialHash: z.string(),
   findings: z.array(findingSchema),
   summary: z.string(),
 }).strict();
