  const owner = readManagedHostRunOwner(paths);
  return {
    runId: spec.runId,
    host: spec.host,
    storyId: spec.storyId,
    phase: spec.phase,
    agentType: spec.agentType,
    reviewRunId: spec.reviewRunId,
    lane: spec.lane,
    cwd: spec.cwd,
    deadlineAt: spec.deadlineAt,
